fleet_event = {
	id = utopia.3323
	hide_window = yes

	trigger = {
		has_global_flag = end_of_the_cycle_complete
		NOT = { has_global_flag = end_of_the_cycle_orders_cooldown }
		owner = { is_country_type = the_reckoning }
		any_playable_country = {
			exists = event_target:the_end_of_the_cycle@this
			event_target:the_end_of_the_cycle@this = { is_same_value = root }
		}
		is_fleet_idle = yes
		any_system = {
			any_system_planet = {
				OR = {
					is_colonizable = yes
					has_owner = yes
				}
				OR = {
					NOT = { has_carrier_flag = exile_planet }
					NOT = {
						any_system = {
							any_system_planet = {
								OR = {
									is_colonizable = yes
									has_owner = yes
								}
								NOT = { has_carrier_flag = exile_planet }
							}
						}
					}
				}
			}
		}
	}

	mean_time_to_happen = {
		months = 3
	}

	immediate = {
		set_timed_global_flag = { flag = end_of_the_cycle_orders_cooldown days = 30 }
		closest_system = {
			limit = {
				any_system_planet = {
					OR = {
						is_colonizable = yes
						has_owner = yes
					}
					OR = {
						NOT = { has_carrier_flag = exile_planet }
						NOT = {
							any_system = {
								any_system_planet = {
									OR = {
										is_colonizable = yes
										has_owner = yes
									}
									NOT = { has_carrier_flag = exile_planet }
								}
							}
						}
					}
				}
			}
			random_system_planet = {
				limit = {
					OR = {
						is_colonizable = yes
						has_owner = yes
					}
					OR = {
						NOT = { has_carrier_flag = exile_planet }
						NOT = {
							any_system = {
								any_system_planet = {
									OR = {
										is_colonizable = yes
										has_owner = yes
									}
									NOT = { has_carrier_flag = exile_planet }
								}
							}
						}
					}
				}
				save_event_target_as = move_to_planet
			}
		}
		queue_actions = {
			find_closest_system = {
				trigger = {
					id = utopia.3323.t1
					any_system_planet = {
						is_same_value = event_target:move_to_planet
					}
				}
				found_system = {
					move_to = this
					find_closest_planet = {
						trigger = {
							id = utopia.3323.t2
							is_same_value = event_target:move_to_planet
						}
						found_planet = {
							move_to = this
							effect = {
								id = utopia.3323.e1
								set_timed_global_flag = { flag = end_of_the_cycle_orders_cooldown days = 30 }
								carrier_event = { id = utopia.3324 }
							}
						}
					}
				}
			}
		}
	}
}

